      c.tube([[sx, py + bh * 0.32, pz], [sx + (ij.x - sx) * 0.5, top - 0.02, pz + es * 0.03], [ij.x, ij.y + 0.02, ij.z]], 0.006, MT.steel, { seg: 10, rs: 4 });
