      c.tube([[hx, R.y - R.h * 0.38, hz - (side ? 0 : R.w * 0.3)], [(hx + e.front) / 2, R.y - R.h * 0.45, (hz + e.fan.z) / 2], [e.front, e.motor.y - 0.05, e.fan.z]], 0.026, MT.hose, { seg: 16, rs: 6 });
