    mass: 1960, r: 85, seats: "2 + 4 combatentes", cap: "100 L + 20 L de reserva", eff: "9,5 km/L", auto: "1.000 km", vmax: 120, skill: "Direção 2 (4x4 com reduzida)", hood: true
