    [1, -1].forEach(function (sd) { c.rod(new V3(-0.6, 2.0, sd * 0.62), new V3(R + 0.06, 1.95, sd * 0.62), 0.025, ACO); c.rod(new V3(R + 0.06, 1.2, sd * 0.62), new V3(R + 0.06, 1.95, sd * 0.62), 0.025, ACO); });
