    ZG.shell(c, { items: items, bottomY: bot, arches: [[o.ax, o.wr, o.wr + 0.08]], W: W, col: col, T: T, holes: [ZG.holeSide(poly), ZG.holeQuad(q)], archInner: W / 2 - o.ww - 0.16 });
    ZG.glassQuad(c, q, "Para-brisa");
