    var zi = W / 2 - 0.13, fab = CM("#3c3e30", { roughness: 0.9 }), trim = CM("#25261f", { roughness: 0.75 }), xd = wsx(belt);
    c.rb(len - 0.28, 0.04, zi * 2, 0.015, MT.carpet, f - len / 2 - 0.04, fl, 0);
